protected void inititalizeRebatePriceHistoryTmp(
    TAMRebateDate _rebateDate,
    TAMRebateTable _rebateTable,
    TAMRebateDeal _rebateDeal,
    Common _journal,
    Common _journalTransaction,
    CurrencyCode _transactionCurrency,
    TransDate _transDate)
{
    next inititalizeRebatePriceHistoryTmp(_rebateDate, _rebateTable, _rebateDeal, _journal, _journalTransaction, _transactionCurrency, _transDate);

    rebatePriceHistoryTmp.PriceComponentCodeName = GUPPriceComponentCodePriceAttributeGroupCombination::find(_rebateTable.PriceComponentCombination).PriceComponentCodeName;
    rebatePriceHistoryTmp.Recipient = _rebateDeal.Recipient;
}
